grammar oracle.parameters.empty.forward_empty.Language hidden(WS)
generate model "urn:intersect:parameter-empty:forward_empty"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: {Model} 'm' child=Forward<false>; Forward<Flag>: <Flag | !Flag> Node<Flag>; Node<Flag>: 'node' (<Flag> name=ID)?;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;
terminal ANY_OTHER: .;

grammar oracle.parameters.empty.root_empty.Language hidden(WS)
generate model "urn:intersect:parameter-empty:root_empty"
import "http://www.eclipse.org/emf/2002/Ecore" as ecore
Model: Forward<false>; Forward<Flag>: <Flag | !Flag> Node<Flag>; Node<Flag>: 'node' (<Flag> name=ID)?;
terminal ID: ('a'..'z')+;
terminal WS: (' '|'\t'|'\r'|'\n')+;
terminal ANY_OTHER: .;
